insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('v4gut2ta9e', 'price:salvator-mundi', 'Salvator Mundi', 'Leonardo da Vinci', 1500, null, 'High Renaissance', 'oil on walnut', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/v4gut2ta9e.jpg', 'The bidding in New York lasted nineteen minutes and shocked the room when it hit 450.3 million dollars. Back in 1958 the same painting had sold for just 45 pounds.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('y29vzfutck', 'price:les-femmes-d-alger', 'Les Femmes d''Alger ("Version O")', 'Pablo Picasso', 1955, null, 'Cubism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/y29vzfutck.jpg', 'Telephone bidders drove this colourful Picasso canvas to 179.4 million dollars in eleven minutes. At the time it became the highest price ever paid for a painting at auction.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('24gmpe5hhj', 'price:portrait-of-elisabeth-lederer', 'Portrait of Elisabeth Lederer', 'Gustav Klimt', 1916, null, 'Art Nouveau', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/24gmpe5hhj.jpg', 'Bidding opened at 130 million dollars and ran for twenty minutes before the hammer fell at 236.4 million. It set a new record for any modern artwork sold at auction.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('6tczuz7kg3', 'price:nu-couche-reclining-nude', 'Nu couché (Reclining Nude)', 'Amedeo Modigliani', 1918, null, null, 'oil on canvas', 'Long Museum, Shanghai', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/6tczuz7kg3.jpg', 'Seven bidders stayed in the race past the hundred-million mark until Chinese collector Liu Yiqian bought the painting for his Shanghai museum. He paid the bill with his American Express card to collect the reward points.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('ckzutqudkr', 'price:portrait-of-dr-gachet', 'Portrait of Dr. Gachet', 'Vincent van Gogh', 1890, null, 'Post-Impressionism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/ckzutqudkr.jpg', 'Japanese businessman Ryoei Saito bought this portrait of van Gogh''s doctor for 82.5 million dollars in just three minutes. Nobody has seen the canvas in public since the mid-1990s.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('awwdqeetuz', 'price:nu-couche-sur-le-cote-gauche', 'Nu couché (sur le côté gauche)', 'Amedeo Modigliani', 1917, null, null, 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/awwdqeetuz.jpg', 'Measuring nearly a metre and a half wide, this is the largest painting Modigliani ever made. A decade earlier it had sold for 26.9 million dollars.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('c9xr28nmxn', 'price:three-studies-of-lucian-freud', 'Three Studies of Lucian Freud', 'Francis Bacon', 1969, null, 'Figurative art', 'oil on canvas (triptych)', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/c9xr28nmxn.jpg', 'Seven bidders chased this three-panel portrait of Bacon''s close friend and rival painter. When the hammer fell after six minutes, it briefly became the priciest artwork ever auctioned.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('uzqry6p754', 'price:twelve-landscape-screens', 'Twelve Landscape Screens', 'Qi Baishi', 1925, null, null, 'ink and colour on paper', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/uzqry6p754.jpg', 'More than fifty bids pushed this set of twelve painted scrolls past 931 million yuan in Beijing. It made Qi Baishi the first Chinese artist to cross the hundred-million-dollar mark.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('8wc37avxu9', 'price:garcon-a-la-pipe', 'Garçon à la pipe', 'Pablo Picasso', 1905, null, 'Expressionism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/8wc37avxu9.jpg', 'Picasso painted this Parisian boy in a wreath of roses when he was only twenty-four years old. In 2004 it became the very first painting to sell for over 100 million dollars at auction.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('7x3qcw6sfk', 'price:the-scream-pastel', 'The Scream (pastel)', 'Edvard Munch', 1895, null, 'Expressionism', 'pastel on board', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/7x3qcw6sfk.jpg', 'The seller''s father had known Munch personally, and the pastel stayed in Norway for decades before twelve intense minutes in New York. Financier Leon Black won it by telephone.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('sv2fpgxw9g', 'price:les-poseuses-ensemble-small', 'Les Poseuses, Ensemble (small version)', 'Georges Seurat', 1888, null, 'Neo-Impressionism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/sv2fpgxw9g.jpg', 'Owned by Microsoft co-founder Paul Allen, this dot-painted studio scene quadrupled the previous auction record for Seurat. Collectors competed heavily during a billion-dollar charity sale.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('2upsu834uz', 'price:nude-green-leaves-and-bust', 'Nude, Green Leaves and Bust', 'Pablo Picasso', 1932, null, 'Surrealism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/2upsu834uz.jpg', 'Picasso painted his muse Marie-Thérèse Walter in a single day, and Los Angeles collector Frances Lasker Brody kept it for nearly sixty years. It sold in nine minutes to an anonymous phone bidder.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('2vhpqtgzgc', 'price:irises-van-gogh', 'Irises', 'Vincent van Gogh', 1889, null, 'Post-Impressionism', 'oil on canvas', 'Getty Museum, Los Angeles', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/2vhpqtgzgc.jpg', 'Van Gogh painted these irises in the asylum garden just a year before his death, yet he never earned real money from his art. In 1987 Alan Bond''s bid made headlines worldwide before the Getty later bought it.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('my3t8xrasj', 'price:dora-maar-au-chat', 'Dora Maar au Chat', 'Pablo Picasso', 1941, null, 'Cubism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/my3t8xrasj.jpg', 'Painted in German-occupied Paris, this portrait shows photographer Dora Maar with a tiny black cat perched behind her shoulder. Nobody expected the bidding to stop just shy of 100 million dollars.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('63ctaqcfga', 'price:la-montagne-sainte-victoire', 'La Montagne Sainte-Victoire', 'Paul Cézanne', 1890, null, 'Post-Impressionism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/63ctaqcfga.jpg', 'Cézanne painted his favourite Provence mountain over and over, and this sun-drenched view led the Paul Allen sale past 137 million dollars. That more than doubled Cézanne''s old auction mark.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('7efugaepf2', 'price:young-girl-with-a-flower-basket', 'Young Girl with a Flower Basket', 'Pablo Picasso', 1905, null, 'Expressionism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/7efugaepf2.jpg', 'Gertrude Stein bought this Rose Period painting straight from Picasso''s studio, and David Rockefeller later hung it in his New York townhouse. When his estate went to Christie''s in 2018, it sold for 115 million dollars.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('4t4aejx8mw', 'price:femme-a-la-montre', 'Femme à la montre', 'Pablo Picasso', 1932, null, 'Surrealism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/4t4aejx8mw.jpg', 'Collector Emily Fisher Landau bought this bold portrait in 1968 and kept it above her fireplace for decades. In 2023 it became Picasso''s second most expensive painting at auction.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('mvqz82ew2u', 'price:silver-car-crash', 'Silver Car Crash (Double Disaster)', 'Andy Warhol', 1963, null, 'Pop art', 'silkscreen ink and spray paint on linen', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/mvqz82ew2u.jpg', 'Five bidders chased Warhol''s two-panel silkscreen after twenty-six years in private hands. Bidding stopped at 105.4 million dollars.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('24b8fe2yxk', 'price:untitled-basquiat-1982', 'Untitled', 'Jean-Michel Basquiat', 1982, null, 'Neo-expressionism', 'oilstick, acrylic and spray paint on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/24b8fe2yxk.jpg', 'Basquiat painted this fierce skull at twenty-one, and back in 1984 it sold at auction for 19,000 dollars. Thirty-three years later Japanese billionaire Yusaku Maezawa paid 110.5 million for it.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('g663ebedga', 'price:portrait-de-l-artiste-sans-barbe', 'Portrait de l''artiste sans barbe', 'Vincent van Gogh', 1889, null, 'Post-Impressionism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/g663ebedga.jpg', 'Van Gogh shaved his beard for his mother''s birthday and painted this late self-portrait in Saint-Rémy. In 1998 a buyer paid 71.5 million dollars for it in New York.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('dnwur69wmn', 'price:meules-monet', 'Meules', 'Claude Monet', 1890, null, 'Impressionism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/dnwur69wmn.jpg', 'Six bidders pushed Monet''s glowing grainstack beyond the hundred-million threshold in New York. Software co-founder Hasso Plattner bought it and brought it to his Museum Barberini in Potsdam.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('x58z467v23', 'price:massacre-of-the-innocents', 'The Massacre of the Innocents', 'Peter Paul Rubens', 1612, null, 'Baroque', 'oil on panel', 'Art Gallery of Ontario, Toronto', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/x58z467v23.jpg', 'For centuries experts mistook this dramatic panel for the work of a lesser Flemish painter. Once Sotheby''s proved it was by Rubens, Canadian collector Kenneth Thomson paid 49.5 million pounds and gave it to Toronto.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('f2n3sfrtpa', 'price:verger-avec-cypres', 'Verger avec cyprès', 'Vincent van Gogh', 1888, null, 'Post-Impressionism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/f2n3sfrtpa.jpg', 'Painted in Arles among blooming peach trees, this spring orchard had not appeared at auction since 1998. It brought 117.1 million dollars during the record-breaking Paul Allen sale.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('2gt4v3cu8b', 'price:orange-red-yellow', 'Orange, Red, Yellow', 'Mark Rothko', 1961, null, 'Abstract Expressionism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/2gt4v3cu8b.jpg', 'Three bidders drove this glowing Rothko canvas to 86.9 million dollars in six minutes. In 2012 that set a new auction record for post-war art.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('75jn2aqjbn', 'price:le-bassin-aux-nympheas', 'Le Bassin aux Nymphéas', 'Claude Monet', 1919, null, 'Impressionism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/75jn2aqjbn.jpg', 'In 1971 this two-metre-wide Giverny pond fetched 320,000 dollars in New York. Thirty-seven years later a buyer sitting in the London saleroom paid nearly 41 million pounds for it.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('zkpmutmn4p', 'price:rideau-cruchon-et-compotier', 'Rideau, Cruchon et Compotier', 'Paul Cézanne', 1894, null, 'Post-Impressionism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/zkpmutmn4p.jpg', 'Whitney family heirs brought this tabletop still life with apples and a jug to Sotheby''s in 1999. Its 60.5-million-dollar price set a Cézanne record that stood for years.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('fj9duy3dm9', 'price:birch-forest-klimt', 'Birch Forest', 'Gustav Klimt', 1903, null, 'Art Nouveau', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/fj9duy3dm9.jpg', 'Klimt painted this quiet carpet of autumn leaves beside Lake Attersee in Austria. In 2022 it became one of five works in a single evening to pass 100 million dollars.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('gtsyfvbkrg', 'price:lady-with-a-fan-klimt', 'Lady with a Fan', 'Gustav Klimt', 1918, null, 'Art Nouveau', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/gtsyfvbkrg.jpg', 'This portrait was still sitting on Klimt''s easel when he died in Vienna in 1918. More than a century later it sold for 85.3 million pounds and became the priciest artwork ever auctioned in Europe.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('7d3hwjyxdc', 'price:vase-with-fifteen-sunflowers', 'Vase with Fifteen Sunflowers', 'Vincent van Gogh', 1889, null, 'Post-Impressionism', 'oil on canvas', 'Sompo Museum of Art, Tokyo', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/7d3hwjyxdc.jpg', 'When this bouquet sold for nearly 25 million pounds in 1987, it tripled the old auction record overnight. That single night launched the modern era of blockbuster art auctions.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('mv69t2kc6e', 'price:suprematist-composition', 'Suprematist Composition', 'Kazimir Malevich', 1916, null, 'Suprematism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/mv69t2kc6e.jpg', 'Malevich left this geometric canvas behind in Berlin in 1927 when he had to return to the Soviet Union. In 2018 it sold for 85.8 million dollars and set a new record for Russian art.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('pqjcbw2m3z', 'price:young-man-holding-a-roundel', 'Portrait of a Young Man holding a Roundel', 'Sandro Botticelli', 1480, null, 'Early Renaissance', 'tempera on panel', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/pqjcbw2m3z.jpg', 'Painted in Florence around 1480, this panel had changed hands in 1982 for 810,000 pounds. Nearly forty years later it reached 92.2 million dollars at Sotheby''s.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('ppddyah6us', 'price:contraste-de-formes', 'Contraste de formes', 'Fernand Léger', 1913, null, 'Cubism', 'oil on burlap', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/ppddyah6us.jpg', 'Léger painted these tumbling red and blue cylinders on rough burlap just before the First World War. The sale at Christie''s nearly doubled his previous auction record.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('cymjvktbta', 'price:portrait-of-a-halberdier', 'Portrait of a Halberdier', 'Pontormo', 1537, null, 'Mannerism', 'oil on panel transferred to canvas', 'Getty Museum, Los Angeles', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/cymjvktbta.jpg', 'The Getty Museum outbid the room at 35.2 million dollars in 1989 to bring this Renaissance guard to California. At the time it set a new high mark for an Old Master painting.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('82ep4addxe', 'price:spring-jeanne', 'Spring (Jeanne)', 'Édouard Manet', 1881, null, 'Impressionism', 'oil on canvas', 'Getty Museum, Los Angeles', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/82ep4addxe.jpg', 'After spending more than a century with one American family, this portrait of Parisian actress Jeanne Demarsy fetched 65.1 million dollars. The Getty Museum bought her straight off the block.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('w5cz83hgpp', 'price:lot-and-his-daughters', 'Lot and His Daughters', 'Peter Paul Rubens', 1614, null, 'Baroque', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/w5cz83hgpp.jpg', 'Once owned by Emperor Joseph I and the Dukes of Marlborough, this huge Rubens had vanished from public view for a century. Four telephone bidders fought for fourteen minutes until it hit 44.9 million pounds.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('xgaava8w97', 'price:modern-rome-campo-vaccino', 'Modern Rome – Campo Vaccino', 'J.M.W. Turner', 1839, null, 'Romanticism', 'oil on canvas', 'Getty Museum, Los Angeles', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/xgaava8w97.jpg', 'Turner''s golden sunset over the Roman Forum sold for nearly 30 million pounds after remaining in the same Scottish family since 1878. The Getty Museum brought it to Los Angeles.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('vd9m7q6h37', 'price:rome-from-mount-aventine', 'Rome, from Mount Aventine', 'J.M.W. Turner', 1835, null, 'Romanticism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/vd9m7q6h37.jpg', 'Having changed hands only once since Turner painted it, this luminous Roman panorama edged past his 2010 record by selling for 30.3 million pounds in London.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('a4v8e3ykt3', 'price:the-foxes', 'The Foxes', 'Franz Marc', 1913, null, 'Expressionism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/a4v8e3ykt3.jpg', 'Returned by Düsseldorf to the heirs of Jewish banker Kurt Grawi, Marc''s curled foxes went on to fetch 42.6 million pounds in London. No work by the painter had ever made more.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('gcvzuxycbp', 'price:jimson-weed-o-keeffe', 'Jimson Weed/White Flower No. 1', 'Georgia O''Keeffe', 1932, null, 'American Modernism', 'oil on canvas', 'Crystal Bridges Museum, Bentonville', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/gcvzuxycbp.jpg', 'O''Keeffe painted this white blossom huge so busy people would stop and notice it. In 2014 it sold for 44.4 million dollars and held the auction record for a woman artist for eleven years.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('czkgm3g6ge', 'price:composition-no-ii', 'Composition No. II', 'Piet Mondrian', 1930, null, 'De Stijl', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/czkgm3g6ge.jpg', 'In 1983 this red-and-black grid became the first abstract painting to pass 2 million dollars at auction. Nearly forty years later it returned to New York and reached 51 million.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('r2cf9fqnb2', 'price:the-dream-the-bed', 'The Dream (The Bed)', 'Frida Kahlo', 1940, null, null, 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/r2cf9fqnb2.jpg', 'Back in 1980 Kahlo''s floating bed cost 51,000 dollars at Sotheby''s. Forty-five years later the same house sold it for 54.7 million dollars, setting an auction record for any work by a woman.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('g8z87wrvdv', 'price:young-woman-seated-at-the-virginals', 'A Young Woman Seated at the Virginals', 'Johannes Vermeer', 1670, null, 'Dutch Golden Age', 'oil on canvas', 'The Leiden Collection, New York', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/g8z87wrvdv.jpg', 'As the last Vermeer in private hands, this small canvas drew huge attention in London in 2004. Once technical tests confirmed Vermeer''s hand, it sold for 16.2 million pounds.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('qbxbu29yyd', 'price:portrait-of-a-man-with-arms-akimbo', 'Portrait of a Man with Arms Akimbo', 'Rembrandt', 1658, null, 'Dutch Golden Age', 'oil on canvas', 'Agnes Etherington Art Centre, Kingston', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/qbxbu29yyd.jpg', 'After forty years out of public view, this bold half-length portrait sold for 20.2 million pounds in London. Archival research later showed the sitter was an Amsterdam ship''s carpenter.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('u7dx86345g', 'price:the-lock-constable', 'The Lock', 'John Constable', 1824, null, 'Romanticism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/u7dx86345g.jpg', 'This Suffolk river scene was the last of Constable''s celebrated six-foot canvases still held privately. Baroness Carmen Thyssen-Bornemisza sold it in London for 22.4 million pounds.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('y29p6bqn4s', 'price:murnau-with-church-ii', 'Murnau with Church II', 'Wassily Kandinsky', 1910, null, 'Expressionism', 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/y29p6bqn4s.jpg', 'Restituted from a Dutch museum to the heirs of Johanna Margarete Stern, this Bavarian landscape sold in London for 37.2 million pounds. Thirteen heirs shared the proceeds.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('sk2eenra5y', 'price:portrait-of-juan-de-pareja', 'Portrait of Juan de Pareja', 'Diego Velázquez', 1650, null, 'Baroque', 'oil on canvas', 'Metropolitan Museum of Art, New York', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/sk2eenra5y.jpg', 'Velázquez painted his enslaved assistant Juan de Pareja in Rome to warm up before portraying Pope Innocent X. In 1970 the Met paid 2.31 million pounds for it, making it the first painting past the million-pound mark.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('wvbctrcabd', 'price:artemis-and-the-stag', 'Artemis and the Stag', 'Unknown (Roman)', -50, null, null, 'bronze', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/wvbctrcabd.jpg', 'Workers dug up this two-thousand-year-old Roman bronze on a building site in Rome in the 1920s. When the Buffalo gallery sold it in 2007, it fetched 28.6 million dollars.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('8be6rm6w9d', 'price:spider-bourgeois', 'Spider', 'Louise Bourgeois', 1996, null, 'Installation art', 'bronze', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/8be6rm6w9d.jpg', 'Bourgeois cast this three-metre bronze spider to honour her mother, who worked as a tapestry restorer in Paris. Its 32.1-million-dollar hammer price set an auction record for any sculpture by a woman.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('y66bunxguw', 'price:self-portrait-yellow-pink', 'Self-Portrait Yellow-Pink', 'Max Beckmann', 1943, null, null, 'oil on canvas', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/y66bunxguw.jpg', 'Beckmann painted himself in exile in Amsterdam and gave the portrait to his wife. In December 2022 a Swiss phone bidder bought it in three minutes for 23.2 million euros, a record for Germany.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('hbtygusurh', 'price:the-flatiron', 'The Flatiron', 'Edward Steichen', 1904, null, 'Modernism', 'gum bichromate over platinum print', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/hbtygusurh.jpg', 'Steichen toned this twilight print of New York''s triangular skyscraper by hand in 1904. Only three prints survive, and Paul Allen''s copy fetched 11.8 million dollars at Christie''s.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, pack_id, active) values ('ye8b2an74j', 'price:rhein-ii', 'Rhein II', 'Andreas Gursky', 1999, null, 'Photorealism', 'chromogenic colour print', 'Private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/ye8b2an74j.jpg', 'Gursky digitally erased every dog walker and factory from a grey photograph of the River Rhine near Düsseldorf. For more than a decade his quiet strip of water held the auction record for any photograph.', null, false) on conflict (id) do update set source_id = excluded.source_id, title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, explicit = excluded.explicit, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = null, active = false, updated_at = now();
